package android.content;import java.io.*;import java.util.*;public class Context {public static final String JOB_SCHEDULER_SERVICE="jobs";public final android.app.job.JobScheduler scheduler=new android.app.job.JobScheduler();public Object getSystemService(String name){return scheduler;}public final File dir;final Map<String,SharedPreferences> prefs=new HashMap<>();public Context(File f){dir=f;dir.mkdirs();}public Context getApplicationContext(){return this;}public SharedPreferences getSharedPreferences(String n,int m){return prefs.computeIfAbsent(n,k->new MemoryPrefs());}public File getFilesDir(){return dir;}public File getCacheDir(){return dir;}public android.content.res.AssetManager getAssets(){return new android.content.res.AssetManager();}}
class MemoryPrefs implements SharedPreferences {final Map<String,Object> data=new HashMap<>();public String getString(String k,String d){return (String)data.getOrDefault(k,d);}public long getLong(String k,long d){return ((Number)data.getOrDefault(k,d)).longValue();}public int getInt(String k,int d){return ((Number)data.getOrDefault(k,d)).intValue();}public boolean getBoolean(String k,boolean d){return (Boolean)data.getOrDefault(k,d);}public Editor edit(){return new Editor(){final Map<String,Object> next=new HashMap<>();public Editor putString(String k,String v){next.put(k,v);return this;}public Editor putLong(String k,long v){next.put(k,v);return this;}public Editor putInt(String k,int v){next.put(k,v);return this;}public Editor putBoolean(String k,boolean v){next.put(k,v);return this;}public Editor remove(String k){next.put(k,null);return this;}public boolean commit(){for(String k:next.keySet())if(next.get(k)==null)data.remove(k);else data.put(k,next.get(k));return true;}public void apply(){commit();}};}}